// Адрес фабрики берётся из конфига сети: второй источник правды об адресах заводить нельзя.
export function escrowFactoryAddress(chainSlug) {
  const chain = chainById(chainSlug || DEFAULT_CHAIN);
  const address = chain && chain.escrow && chain.escrow.address;
  if (!address) throw new Error("в этой сети фабрика эскроу не задеплоена");
  return address;
}

// КАССА КОМИССИИ ИНТЕРФЕЙСА (#103): адрес из конфига сети, как и фабрика. Фабрика кассу больше не заводит -
// она приходит в УСЛОВИЯХ ОРДЕРА, и без неё котировку под ордер не собрать.
export function escrowCashierAddress(chainSlug) {
  const chain = chainById(chainSlug || DEFAULT_CHAIN);
  const cashier = chain && chain.escrow && chain.escrow.cashier;
  if (!cashier) throw new Error("в этой сети не задана касса комиссии (escrow.cashier)");
  return cashier;
}

