  const cashier = escrowCashierAddress(chainSlug);
  const chain = chainById(chainSlug || DEFAULT_CHAIN);

  // СРОКИ И СОЛЬ РЕШАЮТСЯ ЗДЕСЬ, ДО ДОКАЗАТЕЛЬСТВА, И БОЛЬШЕ НИГДЕ.
