  const t1 = readyBy + claimWindowSeconds;
  const salt = providedSalt || newSecret();

  // КОНТЕКСТ СОБИРАЕТСЯ ИЗ ПОЛЕЙ ОРДЕРА - тем же кодом, что у ноды провайдера и у любого проверяющего.
